{"command": "cd /workspace/work && python3 - <<'EOF'
import json, glob
alls=[]
for f in sorted(glob.glob('batch_pats_*.json')):
    alls += json.load(open(f))
def solo(chan_insts, outname):
    cells=[c for c in alls if c['arguments'].get('channel') in chan_insts and c['arguments'].get('note') is not None]
    insts = sorted({c['arguments']['instrument'] for c in cells})
    names={2:'snare',3:'clap',4:'hatc',5:'hato',7:'pluck',9:'bell',10:'zap'}
    vols ={2:64,3:64,4:64,5:64,7:64,9:64,10:64}
    setup=[{"name":"module_new","arguments":{"channels":8,"name":"solo"}}]
    for i in insts:
        setup.append({"name":"sample_load","arguments":{"path":f"/workspace/work/samples/{names[i]}.wav","instrument":i}})
    for c in cells:
        setup.append(c)
    for p in range(12): setup.append({"name":"pattern_set_length","arguments":{"pattern":p,"rows":64}})
    setup.append({"name":"song_set","arguments":{"bpm":140,"speed":6,"length":12,"loop_start":0}})
    for p in range(12): setup.append({"name":"order_set","arguments":{"position":p,"pattern":p}})
    setup.append({"name":"module_render","arguments":{"path":f"/workspace/work/{outname}.wav","rate":44100}})
    json.dump(setup, open(f'batch_{outname}.json','w'))
    print(outname, len(cells))
